WITH gated AS (SELECT model FROM llm_gateway.usage_log WHERE {{ time_filter('timestamp') }} AND model != '' GROUP BY model HAVING count() >= 100), sig AS (SELECT model, count() AS reqs, countIf(is_followup = 1) AS fu, countIf(is_followup = 1 AND signal_count > 0) AS rej_n, sum(guard_blocks + user_rejections + rule_denials) AS fric FROM llm_gateway.request_signals WHERE {{ time_filter('timestamp') }} AND model IN (SELECT model FROM gated) GROUP BY model), spd AS (SELECT model, countIf(is_stream = 1) AS streams, countIf(aborted = 1) AS cancels, countIf(aborted = 2) AS aborts FROM llm_gateway.usage_log WHERE {{ time_filter('timestamp') }} AND model IN (SELECT model FROM gated) GROUP BY model), sess AS (SELECT session_id, argMax(model, timestamp) AS last_model, groupUniqArray(model) AS models FROM llm_gateway.request_log WHERE {{ time_filter('timestamp') }} AND session_id != '' AND coalesce(nullIf(key_id,''), nullIf(api_key_id,''), 'unknown') IN ({{ gf_str_multi('api_key') }}) GROUP BY session_id), swm AS (SELECT m AS model, countIf(last_model != m) AS switches, count() AS n FROM sess ARRAY JOIN models AS m WHERE m IN (SELECT model FROM gated) GROUP BY m), raw AS (SELECT s.model AS model, s.reqs, 100 * s.rej_n / nullIf(s.fu, 0) AS net_rej, 100 * w.switches / nullIf(w.n, 0) AS switch_rate, 100 * p.cancels / nullIf(p.streams, 0) AS cancel_rate, 100 * p.aborts / nullIf(p.streams, 0) AS abort_rate, 100 * s.fric / s.reqs AS fric_rate FROM sig s INNER JOIN spd p ON p.model = s.model LEFT JOIN swm w ON w.model = s.model), idx AS (SELECT model, reqs, net_rej, switch_rate, cancel_rate, abort_rate, fric_rate, ifNull(least(greatest(1 - net_rej / 50, 0.05), 1), 0.5) AS rej_i, ifNull(least(greatest(1 - switch_rate / 100, 0.05), 1), 0.5) AS sw_i, ifNull(least(greatest(1 - cancel_rate / 5, 0.05), 1), 0.5) AS canc_i, ifNull(least(greatest(1 - abort_rate / 5, 0.05), 1), 0.5) AS ab_i FROM raw), scored AS (SELECT model, reqs, net_rej, switch_rate, cancel_rate, abort_rate, fric_rate, rej_i, sw_i, canc_i, ab_i, 100 * power(rej_i * sw_i * canc_i, 1 / 3) AS pai, 100 * sqrt(power(rej_i * sw_i * canc_i, 1 / 3) * ab_i) AS overall, multiIf(100 * sqrt(power(rej_i * sw_i * canc_i, 1 / 3) * ab_i) >= 70, 'good', 100 * sqrt(power(rej_i * sw_i * canc_i, 1 / 3) * ab_i) >= 40, 'mixed', 'poor') AS verdict FROM idx) SELECT model, verdict, round(overall, 1) AS score, round(pai, 1) AS pai, reqs, concat(toString(round(net_rej, 2)), '% (idx ', toString(round(rej_i, 2)), ')') AS rej, concat(toString(round(switch_rate, 2)), '% (idx ', toString(round(sw_i, 2)), ')') AS sw, concat(toString(round(cancel_rate, 2)), '% (idx ', toString(round(canc_i, 2)), ')') AS canc, concat(toString(round(abort_rate, 2)), '% (idx ', toString(round(ab_i, 2)), ')') AS ab, round(fric_rate, 2) AS fric FROM scored WHERE reqs >= 30 AND ('{{ gf_num('include_local') }}' = 'yes' OR model NOT IN (SELECT model FROM llm_gateway.model_registry WHERE is_local = 1)) ORDER BY overall DESC